import React from 'react';
import { Link } from 'react-router-dom';

function ComicCard({ comic }) {
  return (
    <div>
      <img src={comic.image} alt={comic.title} />
      <h3>{comic.title}</h3>
      <p>{comic.genre}</p>
      <Link to={`/comic/${comic.id}`}>Read More</Link>
    </div>
  );
}

export default ComicCard;
